nvstgProgStatCd01"); })())).length || 0))) === 8); } }, { id: "if_invstgStatCode_8", fn: function(){ return ((dma_pageContext.get("invstgStatCode") ?? "") >= 1); } }, { id: "c_if_106_r1", fn: function(){ return ((((dma_proc.get("prelmInvstgProgStatCd07") ?? (() => { throw new Error("unresolved:" + "proc.prelmInvstgProgStatCd07"); })())) && typeof ((dma_proc.get("prelmInvstgProgStatCd07") ?? (() => { throw new Error("unresolved:" + "proc.prelmInvstgProgStatCd07"); })())).getRowCount === 'function' ? ((dma_proc.get("prelmInvstgProgStatCd07") ?? (() => { throw new Error("unresolved:" + "proc.prelmInvstgProgStatCd07"); })())).getRowCount() : ((((dma_proc.get("prelmInvstgProgStatCd07") ?? (() => { throw new Error("unresolved:" + "proc.prelmInvstgProgStatCd07"); })())) == null) ? 0 : (((dma_proc.get("prelmInvstgProgStatCd07") ?? (() => { throw new Error("unresolved:" + "proc.prelmInvstgProgStatCd07"); })())).length || 0))) === 8); } }, { id: "if_invstgStatCode_9_r1", fn: function(){ return ((dma_pageContext.get("invstgStatCode") ?? "") >= 7); } }, { id: "c_if_115_r2", fn: function(){ return ((((dma_pageContext.get("invstgStatDate") ?? "")) && typeof ((dma_pageContext.get("invstgStatDate") ?? "")).getRowCount === 'function' ? ((dma_pageContext.get("invstgStatDate") ?? "")).getRowCount() : ((((dma_pageContext.get("invstgStatDate") ?? "")) == null) ? 0 : (((dma_pageContext.get("invstgStatDate") ?? "")).length || 0))) === 8); } }, { id: "if_invstgStatCode_10_r2", fn: function(){ return ((dma_pageContext.get("invstgStatCode") ?? "") === 97); } }, { id: "img_138", fn: function(){ return ((dma_ListInvstgComDetail.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "ListInvstgComDetail.spotIsuTrdMktTpCd"); })()) === '1'); } }, { id: "img_140", fn: function(){ return ((dma_ListInvstgComDetail.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "ListInvstgComDetail.spotIsuTrdMktTpCd"); })()) === '2'); } }, { id: "c_when_142_txt", fn: function(){ return (!(String(((dma_ListInvstgComDetail.get("comAbbrv") ?? (() => { throw new Error("unresolved:" + "ListInvstgComDetail.comAbbrv"); })())) == null ? '' : ((dma_ListInvstgComDetail.get("comAbbrv") ?? (() => { throw new Error("unresolved:" + "ListInvstgComDetail.comAbbrv"); })()))).length === 0)); } }, { id: "c_when_143_txt", fn: function(){ return (!(String(((dma_ListInvstgComDetail.get("comNm") ?? (() => { throw new Error("unresolved:" + "ListInvstgComDetail.comNm"); })())) == null ? '' : ((dma_ListInvstgComDetail.get("comNm") ?? (() => { throw new Error("unresolved:" + "ListInvstgComDetail.comNm"); })()))).length === 0)); } }, { id: "c_when_160_txt", fn: function(){ return ((dma_ListInvstgComDetail.get("dpFromEmpCnt") ?? (() => { throw new Error("unresolved:" + "ListInvstgComDetail.dpFromEmpCnt"); })()) === '0'); } }, { id: "c_otherwise_161", fn: function(){ return (!(((dma_ListInvstgComDetail.get("dpFromEmpCnt") ?? (() => { throw new Error("unresolved:" + "ListInvstgComDetail.dpFromEmpCnt"); })()) === '0'))); } }, { id: "a_165", fn: function(){ return ((dma_ListInvstgComDetail.get("hpage") ?? (() => { throw new Error("unresolved:" + "ListInvstgComDetail.hpage"); })()) !== ''); } }, { id: "if_dpFromParval", fn: function(){ return ((dma_ListInvstgComDetail.get("dpFromParval") ?? (() => { throw new Error("unresolved:" + "ListInvstgComDetail.dpFromParval"); })()) === '무액면'); } }, { id: "if_dpFromParval_2", fn: function(){ return ((dma_ListInvstgComDetail.get("dpFromParval") ?? (() => { throw new Error("unresolved:" + "ListInvstgComDetail.dpFromParval"); })()) !== '무액면'); } }, { id: "c_if_221", fn: function(){ return ((((dma_proc.get("prelmInvstgProgStatCd07") ?? (() => { throw new Error("unresolved:" + "proc.prelmInvstgProgStatCd07"); })())) && typeof ((dma_proc.get("prelmInvstgProgStatCd07") ?? (() => { throw new Error("unresolved:" + "proc.prelmInvstgProgStatCd07"); })())).getRowCount === 'function' ? ((dma_proc.get("prelmInvstgProgStatCd07") ?? (() => { throw new